<?php
require_once __DIR__ . '/../includes/auth.php'; require_once __DIR__ . '/../includes/db.php'; requireRole(['administrator']);
$conn=db();
$users=$conn->query("SELECT role, status, COUNT(*) total FROM users GROUP BY role,status")->fetch_all(MYSQLI_ASSOC);
$rooms=$conn->query("SELECT h.name hostel_name, COUNT(r.id) rooms, COALESCE(SUM(r.capacity),0) beds, COALESCE(SUM(r.occupied),0) occupied FROM hostel_profiles h LEFT JOIN rooms r ON r.hostel_id=h.id GROUP BY h.id,h.name ORDER BY h.name")->fetch_all(MYSQLI_ASSOC);
$payments=$conn->query("SELECT DATE_FORMAT(payment_date,'%Y-%m') period, COUNT(*) records, COALESCE(SUM(amount),0) amount, COALESCE(SUM(balance),0) balance FROM payment_records GROUP BY period ORDER BY period DESC")->fetch_all(MYSQLI_ASSOC);
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><title>Reports | CourtIQ</title><link rel="stylesheet" href="<?= projectUrl('assets/css/style.css') ?>"><style>@media print{.no-print{display:none!important}.visual-card{break-inside:avoid}}</style></head><body class="dashboard-layout admin-dashboard"><?php require __DIR__ . '/partials/nav.php'; ?><main class="dashboard-content-main container admin-main"><section class="admin-page-heading"><div><span class="admin-eyebrow">REPORTING</span><h1>Operational reports</h1><p>Review occupancy, user and payment summaries.</p></div><button class="btn btn-primary no-print" onclick="window.print()">Print report</button></section><section class="visual-card"><h2>Users by role and status</h2><table class="dash-table"><tr><th>Role</th><th>Status</th><th>Total</th></tr><?php foreach($users as $r): ?><tr><td><?= e(formatRole($r['role'])) ?></td><td><?= e($r['status']) ?></td><td><?= (int)$r['total'] ?></td></tr><?php endforeach; ?></table></section><section class="visual-card"><h2>Hostel occupancy</h2><table class="dash-table"><tr><th>Hostel</th><th>Rooms</th><th>Beds</th><th>Occupied</th><th>Rate</th></tr><?php foreach($rooms as $r): ?><tr><td><?= e($r['hostel_name']) ?></td><td><?= (int)$r['rooms'] ?></td><td><?= (int)$r['beds'] ?></td><td><?= (int)$r['occupied'] ?></td><td><?= $r['beds'] ? round($r['occupied']/$r['beds']*100) : 0 ?>%</td></tr><?php endforeach; ?></table></section><section class="visual-card"><h2>Payment ledger by month</h2><table class="dash-table"><tr><th>Period</th><th>Records</th><th>Amount</th><th>Balance</th></tr><?php foreach($payments as $r): ?><tr><td><?= e($r['period']) ?></td><td><?= (int)$r['records'] ?></td><td>KES <?= number_format((float)$r['amount'],2) ?></td><td>KES <?= number_format((float)$r['balance'],2) ?></td></tr><?php endforeach; ?></table></section></main></body></html>
